import java.util.Locale;

public class Solution {
    static String initials(String fullName) {
        String name = fullName.trim().toUpperCase();
        int lastSpace = name.lastIndexOf(' ');
        String first = name.charAt(0) + ".";
        return lastSpace < 0 ? first : first + name.charAt(lastSpace + 1) + ".";
    }

    static int countWord(String text, String word) {
        String lowerText = text.toLowerCase();
        String without = lowerText.replace(word.toLowerCase(), "");
        return (lowerText.length() - without.length()) / word.length();
    }

    static String censor(String text, String word) {
        String stars = "*".repeat(word.length());
        String lower = word.toLowerCase();
        String capitalized = lower.substring(0, 1).toUpperCase() + lower.substring(1);
        return text.replace(lower, stars).replace(word.toUpperCase(), stars).replace(capitalized, stars);
    }

    static String priceLine(String item, double price) {
        return String.format(Locale.ROOT, "%-12s%8.2f", item, price);
    }
}

unitTests:
test("initials", () -> {
    checkEq(Solution.initials("ada king lovelace"), "A.L.");
    checkEq(Solution.initials("  Grace   Hopper "), "G.H.");
    checkEq(Solution.initials("plato"), "P.");
});

test("counting words", () -> {
    checkEq(Solution.countWord("The cat and the hat. THE end", "the"), 3);
    checkEq(Solution.countWord("theme, then: other", "THE"), 3);
    checkEq(Solution.countWord("banana", "an"), 2);
    checkEq(Solution.countWord("", "x"), 0);
});

test("censoring", () -> {
    checkEq(Solution.censor("Darn, DARN it", "darn"), "****, **** it");
    checkEq(Solution.censor("darned Darn", "DARN"), "****ed ****");
    checkEq(Solution.censor("nothing here", "darn"), "nothing here");
});

test("price lines", () -> {
    checkEq(Solution.priceLine("Tea", 2.5), "Tea             2.50");
    checkEq(Solution.priceLine("Chocolate cake", 12.345), "Chocolate cake   12.35");
    checkEq(Solution.priceLine("Pen", 1234.5).length(), 20);
});

